# aeneid-064 (IX.1-106): t is cut from the edition by A.cut; l, i, n drafted from the Latin.
import sys, os
HERE = os.path.dirname(os.path.abspath(__file__)); sys.path.insert(0, HERE); sys.path.insert(0, os.path.join(HERE, '..', '..'))
import aeneid_lib as A

TITLE = 'Iris ad Turnum. Classis Idaea'
PART = "Turnus Attacks and the Promise to the Ships (IX.1–106)"
TITLE_EN = "Turnus Attacks and the Promise to the Ships — Aeneid IX.1–106"
ABOUT = ("Book 9 opens while Aeneas is far away, upriver with Evander and gone on to the Etruscans. Juno seizes her "
"chance and sends Iris down to Turnus, who is sitting in the grove of his ancestor Pilumnus: Aeneas has left his town, his "
"men and his ships, she tells him, so now is the time to call for horses and chariots and take the Trojan camp while it "
"is in disorder. Turnus knows the goddess by the rainbow she leaves behind her, purifies himself at a stream and loads "
"the sky with prayers. His army moves across the plain, deep and silent as the Ganges or the Nile in their beds, and the "
"Trojans, seeing the dust-cloud rise, shut their gates and man the walls, as Aeneas told them to do before he left: they "
"are to hold the camp and not risk a battle in the open. Turnus rides ahead with twenty horsemen, hurls the first "
"javelin, and circles the walls looking for a way in, like a wolf prowling round a sheepfold at midnight while the lambs "
"bleat safe inside. Finding none, he turns on the fleet moored beside the camp and calls for fire, and his men snatch "
"torches from the hearths. Here the poet stops to ask the Muses which god saved the ships, and tells an old story: when "
"Aeneas was building the fleet on Mount Ida, from pines of a grove sacred to Cybele, the mother of the gods asked her son "
"Jupiter to protect them. He would not make ships built by mortal hands immortal, but he promised that those which "
"reached Italy would lose their mortal shape and become goddesses of the sea, and he swore it by the Styx with a nod "
"that shook Olympus. The part ends on the oath; its fulfilment follows at once.")

U = [
(3, 'audacem ad Turnum.',
 "And while these things were being done in a part far distant,\nIris from the sky sent Saturnian Juno\nto bold Turnus.",
 "While all this was happening in a far-distant place, Juno, daughter of Saturn, sent Iris down from heaven to the bold Turnus.",
 """The first lines of Book 9. 'Atque ea… dum… geruntur', 'and while these things are being done', 'dum' with the present indicative, 'while', even in a past narrative. 'ea' is the business of Book 8: Aeneas has gone upriver to Evander's town and on to the Etruscan camp. 'diversa penitus… parte', 'in a quite different quarter', far away; 'penitus' (deep, utterly) strengthens 'diversa'. 'Irim', Greek accusative of 'Iris', the messenger of Juno, goddess of the rainbow. 'Saturnia Iuno', Juno as Saturn's daughter, the title used when her old grudge is at work. 'audacem', 'bold', Turnus's standing epithet. Elisions 'Atqu(e) ea', 'audac(em) ad'."""),
(4, 'sedebat.',
 "In the grove then by chance of his forefather\nPilumnus Turnus, in a hallowed valley, was sitting.",
 "Turnus happened then to be sitting in the grove of his ancestor Pilumnus, in a hallowed valley.",
 """'Luco… parentis Pilumni', 'in the grove of his forefather Pilumnus', 'parens' in the wider sense, 'ancestor'; Pilumnus, an old Italian god of the household, is Turnus's great-grandfather (10.76 'cui Pilumnus avus', 10.619 'Pilumnusque illi quartus pater'). 'tum forte', 'then, as it happened'. 'sacrata valle', 'in a consecrated valley', locative ablative without a preposition. 'sedebat', 'was sitting', the imperfect setting the scene for the goddess's arrival. No elisions."""),
(5, 'locuta est:',
 "To him thus with rosy, the daughter of Thaumas, mouth spoke:",
 "To him the daughter of Thaumas spoke thus with rosy lips:",
 """'Ad quem', 'to whom', a connecting relative, 'and to him'. 'Thaumantias', 'daughter of Thaumas', a Greek patronymic for Iris: in Hesiod's Theogony Thaumas and the Ocean-nymph Electra are her parents. 'roseo… ore', 'with rosy mouth', framing the name, the bloom of a goddess (Venus 'rosea cervice refulsit', 1.402). Elision 'locut(a) est'."""),
(7, 'attulit ultro.',
 "“Turnus, what to you wishing of the gods to promise no one\nwould dare, the rolling day, look, has brought unasked.",
 "“Turnus, what no god would have dared to promise you for all your wishing, the turning course of time has brought you of its own accord.",
 """Iris's speech opens (6–13). 'quod… nemo auderet', 'what no one would dare', a potential subjunctive in the relative clause, set first as the object of 'attulit'. 'optanti', 'to you wishing', dative of the participle, with 'tibi' understood: however much you wished it. 'divom' = 'divorum', the old genitive plural in '-om', 'of the gods' (the familiar 'divum', as the Latin Library prints it). 'volvenda dies', 'the day that is to roll', time as a turning wheel; the gerundive is used almost as a present passive participle, 'rolling round' (compare 1.269 'volvendis mensibus'). 'dies' is feminine in this sense, a span of time. 'en', 'look!'. 'ultro', 'of its own accord', without being asked. No elisions."""),
(9, 'Euandri.',
 "Aeneas, his city and comrades and fleet left behind,\nthe sceptre of Palatine seeks and the seat of Evander.",
 "Aeneas has left his town, his comrades and his fleet, and gone to seek the sceptre and the home of Evander on the Palatine.",
 """'urbe et sociis et classe relicta', ablative absolute, 'city and comrades and fleet left behind', the singular participle agreeing with the nearest noun; 'urbe' is the fortified camp the Trojans built at the mouth of the Tiber (7.157–159). 'sceptra… sedemque… Euandri', 'the sceptre and the seat of Evander', the king's power and his home; 'sceptra' is plural for singular. 'Palatini', 'Palatine', with 'Euandri': Evander's town stood on the Palatine, the hill of Augustus's own house. 'Euandri' is the Greek spelling of the name; scan it E-van-dri, the u as a consonant. Elision 'urb(e) et'."""),
(11, 'agrestis.',
 "Nor is that enough: the farthest of Corythus he has pierced to the cities,\nand of the Lydians a band, gathered, he arms, country-folk.",
 "Nor is that all: he has made his way deep to the farthest cities of Corythus, and is arming a band of Lydians, rustics gathered from the fields.",
 """'Nec satis', 'nor (is that) enough', the verb left out. 'extremas Corythi… ad urbes', 'to the farthest cities of Corythus', the preposition set between adjective and noun. Corythus is an Etruscan town (later Cortona), the place from which Dardanus, founder of Troy's royal line, set out (3.170, 7.209). 'penetravit', 'has pierced (his way)', deep into strange country. 'Lydorum', 'of the Lydians', the Etruscans, who were believed to have come from Lydia in Asia Minor. 'manum… collectos… agrestis', 'a band… gathered peasants', the two accusatives in apposition; 'agrestis' is accusative plural in '-is'. Iris belittles Aeneas's new allies as a rabble of farmhands. No elisions."""),
(12, 'currus.',
 "Why do you hesitate? Now is the time for horses, now to call for chariots.",
 "Why do you hold back? Now is the time to call for horses, now for chariots.",
 """'Quid dubitas?', 'why do you hesitate?', 'quid' as an adverb, 'why'. 'Nunc tempus (est)… poscere', 'now (it is) the time to call for', with 'est' left out; 'equos' and 'currus' are both objects of 'poscere', which is held back to the second half: 'now (to call for) horses, now to call for chariots'. The repeated 'nunc' (anaphora) hurries him. No elisions."""),
(13, 'castra.”',
 "Break off delays all, and the thrown-into-confusion seize camp.”",
 "Cast off every delay, and seize the camp while it is in disarray.”",
 """'Rumpe moras', 'break off delays', a stock exhortation (Mercury to Aeneas, 4.569 'Heia age, rumpe moras'). 'omnis', accusative plural in '-is' with 'moras'. 'turbata… castra', 'the camp thrown into confusion', with its leader gone; 'arripe', 'snatch', 'seize'. Iris's speech ends, and Greenough closes the mark. Elision 'turbat(a) arripe'."""),
(15, 'arcum.',
 "She spoke, and into the sky on balanced raised herself wings,\nand a huge in her flight cut beneath the clouds arc.",
 "She spoke, and rose into the sky on poised wings, and in her flight cut a vast bow beneath the clouds.",
 """'Dixit', 'she spoke', the usual close of a speech. 'paribus… alis', 'on matched wings', evenly balanced, framing 'se sustulit', 'raised herself'. 'ingentem… arcum', 'a huge arc', the rainbow, her track through the sky, framing the line; 'fuga', 'in her flight', ablative. The second line repeats 5.658, where Iris flew off after setting the Trojan women to burn the ships in Sicily; ships burn again in this part. The double '-que'. No elisions."""),
(17, 'secutus:',
 "The young man knew her, and both to the stars his palms\nraised, and with such her fleeing followed voice:",
 "The young man knew her, and lifting both hands to the stars he sent his voice after her as she fled:",
 """'Adgnovit', Greenough's spelling of 'agnovit', 'recognised', as the Latin Library prints it: he knows the goddess by the rainbow. 'duplicis… palmas', 'both palms', accusative plural in '-is'; 'duplex' here means 'the pair'. Raising the palms to the sky is the gesture of prayer. 'tali… voce', 'with such a voice', framing 'fugientem est', and 'secutus est', 'followed', the auxiliary set between: he calls after her. Elisions 'duplicisqu(e) ad', 'fugient(em) est'."""),
(19, 'in terras?',
 "“Iris, glory of the sky, who you to me on the clouds driven\nbrought down to the earth?",
 "“Iris, glory of heaven, who sent you down to me, borne on the clouds, to earth?",
 """Turnus's speech opens (18–22). 'Iri', vocative of 'Iris'. 'decus caeli', 'ornament of the sky', the rainbow. 'quis te… detulit', 'who brought you down', 'quis' asking which god sent her. 'mihi', 'to me', dative. 'nubibus actam', 'driven on the clouds', 'nubibus' ablative of means. No elisions."""),
(20, 'tempestas?',
 "Whence this so bright, suddenly,\nweather?",
 "Where does this sudden brightness in the sky come from?",
 """'Unde', 'from where?', the verb left out. 'tempestas', 'weather', a spell of sky, here bright and clear, not 'storm': its older sense, from 'tempus', is simply 'a time, a season'. 'tam clara repente', 'so clear, all of a sudden'. Elision 'Und(e) haec'."""),
(21, 'stellas.',
 "Down the middle I see part the sky\nand wandering in the vault the stars.",
 "I see the heavens parting down the middle, and the stars wandering across the sky.",
 """'Medium… discedere caelum', 'the sky parting in the middle', accusative and infinitive after 'video'; the opening sky is an omen, as at Jupiter's thunder in 8.524–529. 'palantis… stellas', 'stars straying', accusative plural in '-is' of the participle of 'palor', 'wander'; stars seen by day, another portent. 'polo', 'in the sky', ablative of place: 'polus', the pole, stands for the whole heaven. No elisions."""),
(24, 'votis.',
 "I follow omens so great,\nwhoever to arms you call.” And thus having spoken, to the water\nhe went forward, and from the surface drew of the stream waters,\nmuch to the gods praying, and loaded the upper air with vows.",
 "I follow omens so great, whoever you are that call me to arms.” With these words he went down to the river, drew water from the top of the stream, and praying long to the gods, he burdened heaven with his vows.",
 """The print has 'vocas. ”Et', a misprint for 'vocas.” Et', corrected here: the closing mark is set after the space and joined to the next word. t keeps the print, because t must match the pinned source; because the mark is joined to 'Et', this unit runs on to the end of the narrative sentence (as at 7.560 and 8.404). 'Sequor omina tanta', 'I follow such great omens'. 'quisquis in arma vocas', 'whoever (you are who) call me to arms', a formula of reverence for a god whose name one is unsure of, or will not presume (Aeneas to Mercury, 4.576–577 'sequimur te, sancte deorum, quisquis es'). Turnus's speech ends. 'effatus', 'having spoken', from the deponent 'effor'. He washes before praying, as a Roman did: 'summo… de gurgite', 'from the top of the stream', the fresh running water; 'lymphas', 'waters', a poetic word. 'multa', 'many things', an internal accusative with 'orans'. 'oneravit… aethera votis', 'loaded the sky with vows', 'aethera' Greek accusative of 'aether'. Elisions 'summoqu(e) hausit', 'oneravitqu(e) aethera'."""),
(26, 'auri;',
 "And now all over the plains the army was going, the open,\nrich in horses, rich in embroidered cloth and in gold;",
 "And now the whole army was advancing across the open plain, rich in horses, rich in embroidered robes and gold;",
 """A new paragraph in Greenough. 'omnis… exercitus', 'the whole army', 'omnis' nominative singular here. 'campis… apertis', 'over the open plains', ablative of the route, framing the line. 'dives equum', 'rich in horses', 'dives' with the genitive; 'equum' = 'equorum', the old genitive plural in '-um' (as 'divom' at 6). 'pictaï vestis', 'of embroidered cloth', 'picta vestis' being cloth 'painted' with the needle: 'pictaï' is the old genitive singular of the first declension in '-āī', three syllables, pic-ta-ī, the diaeresis marking the separate i; Virgil uses it a handful of times for an archaic, Ennian colour ('aulaï' 3.354, 'auraï' 6.747, 'aquaï' 7.464). The Latin Library prints it without the diaeresis. Elision 'Iamqu(e) omnis'."""),
(29, 'est.]',
 "Messapus the front ranks, the rear keep in order\nthe Tyrrhid young men; in the middle of the column the leader, Turnus,\n[he turns about, arms holding, and by his whole head above is.]",
 "Messapus led the front ranks, the young sons of Tyrrhus held the rear together, and in the middle of the column rode Turnus, their leader [moving to and fro, weapons in hand, and taller than the rest by a full head].",
 """Greenough prints 29 inside square brackets as spurious (a line he judges not to be Virgil's here), and it is kept in brackets; the Latin Library leaves it out altogether. It repeats 7.784, where Turnus is first shown among the Italian captains, and the sentence is complete without it. 'Messapus primas acies (ducit)', 'Messapus (leads) the front ranks', the verb understood from the context; Messapus, tamer of horses, son of Neptune (7.691). 'postrema coercent', 'keep the rear in order', 'postrema' neuter plural, 'the hindmost parts'. 'Tyrrhidae iuvenes', 'the young sons of Tyrrhus', the king's herdsman whose tame stag Ascanius shot (7.483–510). 'medio… agmine', 'in the middle of the column', locative ablative. 'vertitur', 'turns this way and that', moving among his men. 'toto vertice supra est', 'is above by his whole head', ablative of the measure of difference. Elision 'supr(a) est'."""),
(32, 'alveo.',
 "As, with seven rising, its calmed streams, deep,\nthrough the silence the Ganges, or with rich flood the Nile\nwhen it flows back from the fields and already has hidden itself in its bed.",
 "So the deep Ganges moves in silence, rising with its seven quiet streams, or the Nile with its fertile flood, when it ebbs from the fields and has settled back into its channel.",
 """A simile with its verb left out: the army moves 'as' ('ceu') the great rivers move, deep, broad and quiet. 'septem surgens sedatis amnibus altus', 'rising deep with its seven calmed streams'; seven streams belong more properly to the Nile, whose seven mouths were proverbial, and Virgil lends the number to the Ganges. 'per tacitum', 'through the silence', the neuter adjective as a noun. 'pingui flumine', 'with its rich stream', the Nile's flood that fattens the fields of Egypt. 'refluit campis', 'flows back from the fields', after the yearly flood; 'campis' ablative of separation. 'se condidit alveo', 'has buried itself in its bed'. 'alveo' is two syllables, al-vyo, the e run into the o (synizesis). No elisions."""),
(34, 'campis.',
 "Here a sudden, with black to gather, dust cloud\nsee before them the Teucrians, and darkness rise over the plains.",
 "At this the Trojans saw ahead of them a sudden cloud of black dust gathering, and a darkness rising over the plain.",
 """'Hic', 'at this point'. 'subitam… nubem', 'a sudden cloud', framing 'nigro… pulvere', 'of black dust', ablative. 'glomerari', 'to be massed together', present passive infinitive: 'nubem glomerari' and 'tenebras insurgere' are accusatives and infinitives after 'prospiciunt', 'they look out and see'. 'Teucri', 'the Trojans', named from Teucer, their first king; 'Teu-' is one syllable. 'campis', 'over the plains', dative with 'insurgere'. Elision 'Teucr(i) ac'."""),
(35, 'Caicus:',
 "First from the facing rampart shouts aloud Caicus:",
 "Caicus was the first to raise the cry, from the rampart that faced them:",
 """'Primus', 'first', the adjective where English uses an adverb. 'ab adversa… mole', 'from the bulwark facing (them)', 'moles' the mass of the earthwork. 'conclamat', 'calls out', raising the alarm. Caicus is a Trojan, named among Aeneas's captains in the storm (1.183). No elisions."""),
(36, 'atra?',
 "“What mass, O citizens, in darkness is rolling black?",
 "“What is that mass, my countrymen, rolling on in the black gloom?",
 """Caicus's speech opens (36–38). 'Quis globus', 'what mass', 'quis' used as an adjective; 'globus' is a ball, a dense body of men. 'o cives', 'citizens', the settlers of the new town. 'caligine… atra', 'in black murk', the dust-cloud, framing 'volvitur', 'rolls on'. No elisions."""),
(39, 'complent.',
 "Bring, quick, steel, give spears, climb the walls,\nthe enemy is here, ho!” With huge shouting through all\nthe Teucrians hide themselves the gates, and the walls fill.",
 "Quick, bring swords, hand out spears, get up on the walls — the enemy is upon us, ho!” With a great clamour the Trojans took shelter behind all their gates and manned the walls.",
 """The print has 'heia! ”Ingenti', a misprint for 'heia!” Ingenti', corrected here: the closing mark is set after the space and joined to the next word. t keeps the print, because t must match the pinned source; because the mark is joined to 'Ingenti', this unit runs on to the end of the narrative sentence. 'Ferte… date… ascendite', three imperatives without connectives (asyndeton), the speech of alarm. 'citi', 'quick', the adjective doing the work of an adverb. 'ferrum', 'steel', swords. 'hostis adest', 'the enemy is here', 'hostis' singular for the whole force. 'heia', 'come on!', a cry of urgency; its i is a consonant, he-ya. Caicus's speech ends. 'per omnis… portas', 'through all the gates', 'omnis' accusative plural; 'condunt se', 'bury themselves', they pour in and shut themselves inside. 'moenia complent', 'fill the walls', they man the ramparts. Elisions 'tel(a) ascendite', and 'hei(a) Ingenti' across the speech mark."""),
(41, 'Aeneas:',
 "For so, departing, had instructed the best in arms\nAeneas:",
 "For so Aeneas, best of warriors, had instructed them when he left:",
 """'Namque', 'for', explaining why they do not go out to fight. 'ita… praeceperat', 'had instructed thus', looking forward to the orders after the colon. 'discedens', 'on leaving', when he set out upriver in Book 8 (these orders are told only now). 'optumus armis', 'best in arms', Greenough's spelling of 'optimus', as the Latin Library prints it; 'armis' ablative of respect. Elision 'Namqu(e) ita'."""),
(43, 'muros.',
 "if any fortune meanwhile should have come,\nneither to draw up should they dare a battle-line nor to trust the field;\nthe camp only and, safe by the mound, they should keep the walls.",
 "if anything should happen in the meantime, they were not to venture to form a line of battle or to trust themselves to the open field, but only to hold the camp and the walls, safe behind their earthwork.",
 """Aeneas's orders in reported speech. 'siqua… fortuna fuisset', 'if any chance should have come about', Greenough's 'siqua' for 'si qua' (as the Latin Library prints it), 'qua' the indefinite after 'si'; the pluperfect subjunctive stands for a future perfect of his actual words. 'neu… auderent… neu (crederent)', 'that they should not dare… nor trust', a negative indirect command with 'ne' understood; 'neu' = 'and not', 'nor'. 'struere aciem', 'to draw up a line of battle'. 'credere campo', 'to trust (themselves) to the plain'. 'castra… servarent', 'they should keep the camp', the positive order following without a connective. 'tutos… aggere muros', 'the walls safe with their rampart', 'aggere' ablative of means. 'interea' is four syllables, in-te-re-a. Elisions 'siqu(a) interea', 'struer(e) auderent', 'mod(o) et'."""),
(46, 'hostem.',
 "So although to join hand shame and anger point,\nthey throw shut the gates nonetheless, and the orders carry out,\nand armed in the hollow await towers the enemy.",
 "So, though shame and anger urged them to close with the foe, they barred the gates all the same, did as they were told, and waited, armed, for the enemy in their hollow towers.",
 """'conferre manum', 'to bring hand together (with the enemy)', to fight hand to hand. 'pudor iraque monstrat', 'shame and anger show (them the way)', the singular verb with two subjects, as often. 'obiciunt portas', 'they throw the gates against (the enemy)', they shut them; 'obiciunt' scans ob-yi-ci-unt, with the i after the prefix a consonant. 'praecepta facessunt', 'they carry out the orders', 'facesso', an intensive of 'facio', 'do with zeal'. 'cavis… turribus', 'in their hollow towers', the wooden towers on the rampart, framing 'expectant', Greenough's spelling of 'exspectant' (the Latin Library prints the double s). 'hostem', 'the enemy', singular collective again. Elision 'Erg(o) etsi'."""),
(49, 'adest;',
 "Turnus, as ahead flying the slow he had outstripped column,\nby twenty picked of the horsemen attended, also at the city\nunlooked-for is present;",
 "Turnus, who had flown on ahead of his slow-moving column with twenty picked horsemen, appeared before the town unlooked-for;",
 """'Turnus ut… praecesserat', 'Turnus, as he had gone on ahead of', 'ut' with the pluperfect indicative, 'as', explaining how he comes to arrive first; the 'et' that follows joins loosely, 'and (so) he is at the city', as though 'ut' had not been written. 'ante volans', 'flying ahead', of a horseman at the gallop. 'tardum… agmen', 'the slow column', framing. 'viginti lectis equitum', 'by twenty picked men of the horsemen', 'equitum' partitive genitive; 'comitatus', 'accompanied', passive in sense. 'urbi… adest', 'is at the city', dative with 'adsum'; the Trojan camp is called a 'city'. 'improvisus', 'unforeseen', taking them by surprise. No elisions."""),
(50, 'rubra.',
 "with spots whom a Thracian, white,\ncarries horse, and with crest covers a helmet golden, red.",
 "a Thracian horse dappled with white carried him, and a golden helmet with a red crest covered his head.",
 """'maculis quem Thracius albis portat equus', 'whom a Thracian horse with white spots carries', a connecting relative ('and him…'); 'maculis… albis', ablative of description, framing the clause. Thracian horses were famous (Homer's Rhesus brought the finest to Troy). 'cristaque… rubra', 'with a red crest', ablative of description again, framing the rest of the line; 'tegit galea aurea', 'a golden helmet covers (him)'. Elision 'gale(a) aurea'."""),
(53, 'infert.',
 "“Is there anyone, with me, young men, who first against the enemy?\nLook!” he says, and a javelin, whirling it, sends out into the air,\nthe beginning of the fight, and onto the plain himself, high, he carries.",
 "“Which of you, my young men, will be the first with me against the enemy? See!” he cried, and whirling a javelin he sent it flying into the air to begin the fight, and rode out tall in the saddle on to the plain.",
 """The print has 'En, ”ait', a misprint for 'En,” ait', corrected here: the closing mark is set after the space and joined to the next word. t keeps the print, because t must match the pinned source; the speech opens and closes in this unit. 'Ecquis erit… qui primus (ibit) in hostem?', 'will there be anyone who (will go) first against the enemy?', the verb of motion left out in his eagerness. 'mecum', 'with me', set off by commas. 'En', 'look!', as he throws. 'attorquens', 'whirling (it) at (them)', 'ad' + 'torqueo'. 'principium pugnae', 'the beginning of battle', in apposition to the whole act: the first spear thrown opens the fight, as the Roman fetial priest declared war by hurling a spear into enemy land. 'campo sese… infert', 'carries himself onto the plain', 'campo' dative of direction; 'arduus', 'towering', high on his horse. Elisions 'iacul(um) attorquens', 'pugn(ae) et', 'ses(e) arduus'."""),
(55, 'horrisono:',
 "With a shout they receive him, his comrades, and with a roar follow\nhorror-sounding:",
 "His comrades greeted him with a shout and followed with a roar that struck terror:",
 """'Clamore excipiunt', 'they take (him) up with a shout', 'clamore' ablative of manner. The Latin Library reads 'clamorem excipiunt', 'they take up the cry', catching his shout and answering it: the picture is slightly different, the scene the same. 'fremitu… horrisono', 'with a roar dreadful-sounding', the adjective run over into the next line for weight; 'horrisonus' is a poetic compound, 'horror' + 'sono'. Elision 'Clamor(e) excipiunt'."""),
(57, 'fovere.',
 "of the Teucrians they marvel at the inert hearts:\nthat not to the fair they give themselves field, not to meet carry\narms the men, but the camp hug.",
 "they marvelled at the sluggish hearts of the Trojans, that the men would not come out on to fair and open ground, nor take up arms to meet them, but clung to their camp.",
 """'Teucrum' = 'Teucrorum', the old genitive plural in '-um', 'of the Trojans'. 'mirantur', 'they wonder at', both the 'inertia corda', 'sluggish hearts', and what follows in accusative and infinitive: 'viros non… dare se… non… ferre… sed… fovere', 'that men do not give themselves… do not bring… but cherish'. 'aequo… campo', 'to the level field', the plain where both sides fight on equal terms; dative after 'dare se'. 'obvia ferre arma', 'to carry weapons to meet (them)'. 'castra fovere', 'to hug the camp', as a bird broods on its nest. 'fovere' is the present infinitive of 'foveo', with a long e (fo-vē-re), not a perfect in '-ere'. Its final e elides into 'Huc', which opens the next sentence: 'fover(e) huc'."""),
(58, 'quaerit.',
 "Here, wild, and here\nhe circles on his horse the walls, and an approach through pathless places seeks.",
 "This way and that he rode round the walls in a fury, looking for a way in where no way was.",
 """'Huc… atque huc', 'this way and that', the repeated adverb tracing his circuits. 'turbidus', 'in turmoil', wild with anger. 'lustrat equo muros', 'he goes round the walls on horseback', 'lustro' 'to go round, survey'; 'equo' ablative of means. 'per avia', 'through pathless places', 'avius' (a + via), the neuter plural as a noun. Elisions 'fover(e) huc', across the full stop, and 'atqu(e) huc'."""),
(61, 'media;',
 "And as when, at a full lying in ambush, a wolf, sheepfold,\nwhen he growls at the pens, having endured winds and rains,\nat night, past the middle;",
 "As when a wolf lying in wait by a crowded sheepfold snarls at the pens past midnight, after enduring wind and rain;",
 """A simile, on the model of Homer's lion prowling round the fold (Iliad 12, of Sarpedon at the Greek wall). 'Ac veluti… cum', 'and as when'. 'pleno… ovili', 'a full sheepfold', dative with 'insidiatus', 'lying in ambush for', framing 'lupus'. 'fremit ad caulas', 'growls at the pens', the wattled fences. 'ventos perpessus et imbris', 'having endured winds and rains', 'imbris' accusative plural in '-is'. 'nocte super media', 'beyond the middle of the night', 'super' as a preposition after its noun. No elisions."""),
(64, 'fauces:',
 "safe beneath their mothers the lambs\ntheir bleating keep up; he, savage and shameless in his anger,\nrages against the out-of-reach; gathered wears him out, for eating,\nfrom long ago, the madness, and, dry of blood, his jaws:",
 "the lambs, safe beneath their mothers, keep up their bleating, while he, savage and relentless in his anger, rages against what he cannot reach, worn out by a ravening hunger long gathering and by his jaws dry of blood:",
 """'tuti sub matribus agni', 'the lambs safe under their mothers', the bleating that maddens him. 'balatum exercent', 'keep their bleating at work', keep it up. 'ille', 'he', the wolf. 'asper et improbus ira', 'savage and shameless in anger'; 'improbus' is what knows no limit, ravenous. 'saevit in absentis', 'rages against those out of reach', 'absentis' accusative plural in '-is', absent from his jaws though near. 'collecta… ex longo rabies', 'the madness gathered over a long time', 'ex longo (tempore)'; 'edendi', 'of eating', genitive of the gerund with 'rabies', 'a frenzy to eat'. 'fatigat', 'wears out', singular with two subjects, 'rabies' and 'fauces'. 'siccae sanguine fauces', 'jaws dry of blood', 'sanguine' ablative of separation. Elisions 'balat(um) exercent', 'ill(e) asper'."""),
(66, 'ardet.',
 "not otherwise, in the Rutulian, the walls and camp viewing,\nkindle the angers; in his hard resentment bones burns.",
 "even so the Rutulian, as he surveyed the walls and the camp, felt his anger flare, and resentment burned in his hard bones.",
 """'haud aliter', 'not otherwise', closing the simile. 'Rutulo… tuenti', 'to the Rutulian as he gazes at', dative of reference: 'in him' his angers blaze. 'ignescunt irae', 'angers catch fire', the inceptive '-sco', 'begin to burn'; plural 'irae', fits of rage. 'duris… ossibus', 'in his hard bones', locative ablative, framing 'dolor', 'resentment', the sting of wounded pride. No elisions."""),
(68, 'aequum?',
 "By what may he try means an approach, and what way the shut-in\nmight shake Teucrians from the rampart and pour onto the level?",
 "How was he to attempt an entrance? What way could shake the Trojans out from behind their rampart and spill them on to the open plain?",
 """Turnus's own thoughts, in deliberative questions, 'how is he to…?', with no verb of thinking to introduce them. 'Qua… ratione', 'by what means', framing 'temptet aditus', 'is he to try an approach', 'aditus' accusative plural. 'quae via… excutiat… atque effundat', 'what way might shake out… and pour out', subjunctives of the same kind. 'clausos… Teucros', 'the shut-in Trojans', framing. 'vallo', 'from the palisade', ablative of separation. 'in aequum', 'onto the level', open ground. Elisions 'ration(e) aditus', 'vall(o) atque', 'atqu(e) effundat'."""),
(72, 'implet.',
 "The fleet, which to the side of the camp adjoining lay hidden,\nby mounds fenced round about and by river waters,\nhe attacks, and of his comrades fire demands, exulting,\nand his hand with pine blazing, hot, fills.",
 "He fell upon the fleet, which lay hidden against the flank of the camp, fenced in by earthworks and the waters of the river; he called on his exultant comrades for fire, and in his heat filled his own hand with a blazing pine-brand.",
 """'Classem', 'the fleet', object of 'invadit', set first with its relative clause before the verb. The ships are drawn up in the Tiber beside the camp. 'lateri… adiuncta', 'joined to the side', dative with the participle; 'adiuncta' scans ad-yun-cta, the i after the prefix a consonant. 'latebat', 'lay hidden', screened by the camp. 'aggeribus saeptam circum', 'fenced round with mounds', 'circum' an adverb. 'fluvialibus undis', 'with river waters'. 'socios… incendia poscit', 'demands fire of his comrades', 'posco' with two accusatives, the person asked and the thing asked for; 'incendia', 'fires', plural. 'ovantis', 'exulting', accusative plural in '-is' with 'socios'. 'pinu flagranti', 'with blazing pine', a torch, ablative with 'implet'. 'fervidus', 'hot', of his temper. Elisions 'castror(um) adiuncta', 'circ(um) et', 'sociosqu(e) incendia'."""),
(74, 'atris.',
 "Then indeed they set to it — drives them the presence of Turnus —\nand all with torches the youth girds itself, black.",
 "Then they set to in earnest, urged on by Turnus's presence, and all the young men armed themselves with smoky torches.",
 """'Tum vero', 'then indeed', marking the moment of action. 'incumbunt', 'they lean in', put their weight to the work. 'urget praesentia Turni', 'the presence of Turnus urges (them)', a parenthesis giving the reason. 'omnis… pubes', 'all the youth', the young fighting men, 'omnis' nominative singular. 'accingitur', 'girds itself', the passive used as a middle, 'arms itself'. 'facibus… atris', 'with black torches', black with smoke, framing the line. Elisions 'ver(o) incumbunt', 'atqu(e) omnis'."""),
(76, 'favillam.',
 "They plundered the hearths; pitchy carries the smoky light\nthe torch, and mingled Vulcan to the stars ash.",
 "They stripped the hearths of fire; the smoky pine-brands gave out a pitch-black light, and the god of fire carried up a swirl of ash to the stars.",
 """'Diripuere' = 'diripuerunt', the perfect in '-ere' (the regular poetic form by now), 'they tore apart', 'plundered': they snatch burning brands from the hearths. 'piceum… lumen', 'pitchy light', black and smoking, framing 'fert fumida', 'the smoky (torch) carries', and 'fumida… taeda', 'the smoky pine-torch', runs over the line-end. 'Volcanus', 'Vulcan', the god of fire for fire itself (metonymy); 'fert' serves him too: 'Vulcan carries the mingled ash to the stars'. 'commixtam… favillam', 'the mingled ash', framing. Elision 'taed(a) et'."""),
(78, 'avertit?',
 "What god, O Muses, so savage fires from the Teucrians\nturned away?",
 "What god, O Muses, turned such savage fires away from the Trojans?",
 """The print has 'musae', a misprint for 'Musae', corrected here: Greenough capitalises the Muses everywhere else ('Musa' 1.8, 'Musis' and 'Musarum' 9.774–775, 'Musa' 10.191). t keeps the print, because t must match the pinned source. A new paragraph in Greenough. The poet breaks off the story to call on the Muses, the epic signal that something marvellous follows. 'Quis deus… avertit', 'what god turned away'. 'tam saeva incendia', 'such savage fires'. 'Teucris', 'from the Trojans', dative of disadvantage with a verb of taking away. Elision 'saev(a) incendia'."""),
(78, 'ignes?',
 "So great from the ships who drove off fires?",
 "Who drove such great flames from the ships?",
 """The same question again, put another way. 'Tantos… ignes', 'such great fires', framing the line. 'ratibus', 'from the rafts', poetic for ships, dative again with a verb of removing. 'depulit', 'drove off'. 'ignes' is Greenough's accusative plural; the Latin Library prints 'ignis', the same word. No elisions."""),
(79, 'perennis.',
 "Tell. Ancient is the warrant for the deed, but the fame everlasting.",
 "Tell me. The faith that vouches for it is old, but its fame never dies.",
 """'Dicite', 'tell', plural imperative to the Muses. 'Prisca fides facto (est), sed fama perennis (est)', 'old is the belief in the deed, but the report of it lasting', with 'est' left out twice. 'facto', dative, 'given to the deed'. The poet admits the tale is hard to credit, a matter of old belief, and claims it is kept alive by tradition all the same. No elisions."""),
(83, 'Iovem:',
 "At the time when first on Phrygian he was shaping Ida\nAeneas his fleet, and of the sea to seek the deeps was preparing,\nshe herself, of the gods it is said the mother, the Berecyntian, great\nwith words these addressed Jupiter:",
 "At the time when Aeneas first began to build his fleet on Phrygian Ida and was making ready to seek the open sea, the Berecyntian mother of the gods herself, so it is said, spoke these words to great Jupiter:",
 """The story goes back to the building of the fleet below Mount Ida after the fall of Troy (3.5–6). 'Tempore quo', 'at the time when'. 'Phrygia… in Ida', 'on Phrygian Ida', the mountain above Troy, framing 'formabat', 'was shaping'. 'pelagi… alta', 'the deeps of the sea', 'alta' neuter plural as a noun. 'ipsa deum… genetrix Berecyntia', 'the Berecyntian mother of the gods herself': Cybele, the great mother-goddess of Phrygia, named from Mount Berecyntus, here one with Rhea, mother of Jupiter. 'deum' = 'deorum', the genitive plural in '-um'. 'fertur… adfata (esse)', 'is said to have addressed', the poet again passing on what is told. 'magnum… Iovem', 'great Jupiter', framing. Elisions 'class(em) et', 'peter(e) alta'."""),
(84, 'Olympo.',
 "“Grant, son, to her asking,\nwhat your dear mother, Olympus mastered, asks of you.",
 "“Grant, my son, to one who asks it what your dear mother begs of you, now that Olympus is yours.",
 """Cybele's speech opens (83–92). 'Da… petenti', 'grant to (me) asking', the participle as a noun, dative. 'nate', 'son', vocative. 'quod… te poscit', 'what she asks of you', 'posco' with two accusatives again. 'tua cara parens', 'your dear mother', speaking of herself in the third person. 'domito… Olympo', ablative absolute, 'Olympus having been mastered', 'now that you rule heaven': she asks as the mother of the king of the gods. No elisions."""),
(87, 'acernis:',
 "[A pine-wood to me, loved through many years,]\na grove on the citadel there was, the highest, whither offerings they brought,\nwith dark pitch-pine and with trunks shadowy of maple:",
 "[I had a wood of pines, dear to me for many years,] a grove on the topmost height, where men brought their offerings, shadowy with dark pitch-pine and maple trunks:",
 """Greenough prints 85 inside square brackets as spurious, and it is kept in brackets; the Latin Library prints it without them. Without it the sentence still stands, 'lucus… fuit', 'there was a grove', though 'mihi' goes with it. 'Pinea silva mihi (fuit)', 'there was to me a pine-wood', a dative of possession (as 'sunt mihi'); 'dilecta', 'beloved'. 'lucus', 'grove', a sacred wood. 'in arce… summa', 'on the topmost height', of Ida, framing 'fuit'. 'quo sacra ferebant', 'to which they brought offerings', 'quo' the relative adverb, 'whither'. 'nigranti picea', 'with darkening pitch-pine', ablative of description; 'trabibusque… acernis', 'and trunks of maple', framing 'obscurus', 'dark, shadowy'. Elision 'trabibusqu(e) obscurus'."""),
(89, 'angit.',
 "these I to the Dardanian young man, when of a fleet he had need,\ngladly gave; now me, troubled, fear anxious chokes.",
 "these trees I gave gladly to the young Dardanian when he needed a fleet; now an anxious fear torments me in my distress.",
 """'has', 'these', feminine: the trees, 'pinus' and 'picea' being feminine. 'Dardanio iuveni', 'to the Dardanian young man', Aeneas, of the line of Dardanus. 'cum classis egeret', 'when he was in need of a fleet', 'classis' genitive singular with 'egeo'. 'laeta dedi', 'I gladly gave', 'laeta' adjective for adverb. 'sollicitam (me)', 'me, troubled', the pronoun understood. 'timor anxius angit', 'anxious fear chokes', 'anxius' and 'angit' from the same root ('ango', 'squeeze, throttle'), the sound doubling the sense. No elisions."""),
(90, 'parentem:',
 "Loose my fears, and this by her prayers allow to have power your parent:",
 "Set my fears at rest, and let your mother's prayers have power to win this:",
 """'Solve metus', 'loose my fears', 'metus' accusative plural. 'hoc… sine posse parentem', 'allow your parent to be able (to do) this', 'sine', imperative of 'sino', 'allow', with accusative and infinitive. 'precibus', 'by her prayers'. 'hoc' points forward to the request after the colon. Elision 'atqu(e) hoc'."""),
(92, 'ortas.”',
 "that not by voyage shaken any nor by whirlwind of wind\nthey be overcome; let it profit them on our mountains to have sprung.”",
 "let no voyage batter them, no gust of the gale overpower them; let it serve them well that they grew on my mountains.”",
 """'ne… neu… vincantur', 'that they not be overcome', explaining 'hoc': the ships are not to be defeated by sea or storm. 'cursu… ullo', 'by any voyage', framing 'quassatae', 'shaken'. 'turbine venti', 'by the whirl of the wind'. 'prosit… ortas (esse)', 'let it profit (them) to have sprung', a jussive subjunctive; 'ortas' is the participle of 'orior', agreeing with 'eas' (the ships) understood. 'nostris… montibus', 'our mountains', the royal plural, framing 'in'. Cybele's speech ends, and Greenough closes the mark. Elision 'quassat(ae) ullo'."""),
(93, 'mundi:',
 "Her son to her in reply, who turns the stars of the universe:",
 "Her son, who turns the stars of the firmament, answered her:",
 """'Filius huic contra (inquit)', 'her son (said) to her in reply', the verb of speaking left out, as so often. 'torquet qui sidera mundi', 'who turns the stars of the universe', 'qui' set after the first word of its clause; Jupiter as ruler of the turning heavens. 'mundi', 'of the world', the ordered cosmos. No elisions."""),
(94, 'istis?',
 "“O mother, where the fates are you calling, or what do you seek for these?",
 "“Mother, where are you trying to bend the fates? What is this you ask for those ships of yours?",
 """Jupiter's reply opens (94–103). 'quo fata vocas', 'whither do you call the fates?', as if to summon destiny off its course. 'aut quid petis istis', 'or what are you seeking for those (of yours)', 'istis' dative, the ships she cares for; 'iste' often has the sense 'that of yours'. No elisions."""),
(97, 'Aeneas?',
 "With mortal hand made should immortal keels\nright have, and sure through uncertain perils pass\nAeneas?",
 "Are keels built by mortal hands to have the privilege of immortality, and is Aeneas to pass through uncertain dangers with his safety certain?",
 """Indignant questions with deliberative subjunctives, 'are they to have…?'. 'Mortaline' = 'mortali' + '-ne', the question-particle on the emphatic word. 'manu factae', 'made by hand'. 'immortale… fas', 'an immortal right', what the gods allow, framing 'carinae'; 'carinae', 'keels', for ships. 'certus', 'sure', of the outcome, set against 'incerta', 'uncertain'. 'lustret', 'is he to pass through', traverse. Elisions 'fact(ae) immortale', 'certusqu(e) incerta'."""),
(97, 'potestas?',
 "To what god such permitted power?",
 "What god was ever allowed such power?",
 """'Cui… deo', 'to what god', 'cui' as an interrogative adjective. 'tanta… permissa (est) potestas', 'has such power been granted', 'est' left out. Even Jupiter cannot override fate and the order of things. 'cui' is one syllable here. No elisions."""),
(100, 'arva,',
 "Nay rather, when, their service done, the end and the harbours they shall hold,\nthe Ausonian, one day, whichever shall have escaped the waves\nand the Dardanian leader to the Laurentine shall have carried fields,",
 "No: when their work is done and they reach their journey's end in the harbours of Ausonia, then whichever of them has come safely through the waves and carried the Dardanian leader to the fields of Laurentum,",
 """A comma-ended unit: Jupiter's last sentence runs to 103 and is split at its comma. 'Immo', 'nay rather', correcting what came before. 'ubi… tenebunt', 'when they shall hold', future. 'defunctae', 'having discharged (their task)', from 'defungor'. 'finem portusque… Ausonios', 'the end and the Ausonian harbours', their goal in Italy ('Ausonia', an old name for it). 'quaecumque evaserit… vexerit', 'whichever shall have escaped… shall have carried', future perfects: the plural ships become singular, 'any one of them that…'. 'Dardanium… ducem', 'the Dardanian leader', Aeneas. 'Laurentia… arva', 'to the Laurentine fields', accusative of goal, the land of King Latinus. Elisions 'Imm(o) ubi', 'quaecumqu(e) evaserit'."""),
(103, 'pontum.”',
 "the mortal I will snatch away form, and of the great I will bid\nsea them be goddesses, such as Nereus's daughter Doto\nand Galatea cut the foaming with breast sea.”",
 "from those I will take away their mortal shape and bid them be goddesses of the great sea, like Doto, daughter of Nereus, and Galatea, who cleave the foaming waters with their breasts.”",
 """'mortalem eripiam formam', 'I will snatch away (its) mortal form'. 'magni… aequoris… deas', 'goddesses of the great sea', framing 'iubebo', 'I will bid'. 'qualis', 'such as', nominative singular agreeing with the nearer name; 'Nereia Doto', 'Doto, daughter of Nereus', 'Nereia' a Greek patronymic adjective. Doto and Galatea are Nereids, sea-nymphs, both in Homer's list of them (Iliad 18). 'secant', 'cut', plural for the pair. 'spumantem… pontum', 'the foaming sea', framing. 'pectore', 'with the breast', of swimming. Jupiter's speech ends, and Greenough closes the mark. Elision 'mortal(em) eripiam'."""),
(106, 'Olympum.',
 "He had spoken, and this, as fixed, by the rivers of his Stygian brother,\nby the with pitch seething and with black whirlpool banks,\nhe nodded, and the whole with his nod made tremble Olympus.",
 "He had spoken, and he swore it fixed, nodding assent by the rivers of his Stygian brother, by the banks that seethe with pitch in their black whirlpool, and with his nod he made all Olympus quake.",
 """'Dixerat', 'he had spoken', pluperfect closing the speech. 'idque ratum… adnuit', 'and nodded it ratified', 'ratum' predicative, 'as settled'. 'Stygii… fratris', 'of his Stygian brother', Pluto, lord of the underworld, framing 'per flumina'. An oath by the Styx binds the gods themselves. 'per pice torrentis… ripas', 'by the banks seething with pitch', 'torrentis' accusative plural in '-is', framing the line; 'atra… voragine', 'with black whirlpool'. 'totum… Olympum', framing 'nutu tremefecit', 'with his nod made tremble': Homer's Zeus nods to Thetis and great Olympus shakes (Iliad 1). The three lines return word for word at 10.113–115. No elisions."""),
]

P = A.part('aeneid-064'); L = A.lines_of(P); paras = {l['n'] for l in L if l['p']}
cuts = A.cut(P, [(u[0], u[1]) for u in U])
sents = []; prev_end_line = None
for (t, ln), (_, _t, l, i, n) in zip(cuts, U):
    u = {'t': t, 'l': l, 'i': i, 'n': n}
    if prev_end_line != ln and ln in paras: u['p'] = True
    u['v'] = True; u['ln'] = ln; sents.append(u)
    prev_end_line = ln + t.count('\n')
    if t.count('\n') != l.count('\n'): print('LINE COUNT', ln, repr(t[:30]), t.count('\n'), l.count('\n'))
    if t.count('\n') > 4: print('TOO LONG', ln)
    if '\n' in i: print('NEWLINE IN i', ln)
    if t.rstrip('”]')[-1] not in A.TERMINAL + ',': print('ENDING', ln, repr(t[-12:]))
A.jdump({'title': TITLE, 'titleEn': TITLE_EN, 'part': PART, 'about': ABOUT, 'sentences': sents}, os.path.join(HERE, 'units.json'))
print(len(sents), 'units')
